import java.util.*; public class Week04Problem05{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();if(n<=0)return;int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;while(l<r){int m=(l+r)/2;if(a[m]>a[r])l=m+1;else r=m;}System.out.println(a[l]);}}